    # The extra launch allowance applies only when the caller kept the default capacity;
    # an explicit capacity is a hard burst cap.
    self._burst = self.DEFAULT_BURST if capacity is None else capacity
    self.capacity = self.DEFAULT_CAPACITY if capacity is None else capacity
    self.refill_per_sec = refill_per_sec
    self.clock = clock or MonotonicClock()
    self._buckets: dict[str, TokenBucket] = {}

def _bucket(self, key: str) -> TokenBucket:
